/* ================= VELİ PANELİ (ayrı uygulama · B2B panel tasarım dokümanı Bölüm 04 yapısı, veli gözünden) ================= */
Object.assign(DEF_SUB,{'v-ders':'tum','v-calisma':'etkinlik','v-sinav':'yaklasan'});
const VDAYS=['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'];
const vMon=(iso=stuToday())=>{const d=new Date(iso+'T12:00:00');return isoAdd(iso,-((d.getDay()+6)%7))};
const vFirst=()=>myStu().first;
const vPar=()=>myStu().parents[0];
const vHi=()=>`${vPar().name.split(' ')[0]} ${vPar().rel==='Baba'?'Bey':'Hanım'}`;
function ensurePar(){if(DB.par)return;DB.par={settings:{chApp:1,chMail:1,chSms:0,tAct:1,tExam:1,tMsg:1,tBadge:1,tWeek:1,tAlert:1,tRev:0,sumDay:'Pazar',sumTime:'19:00',sumFmt:'Uygulama + e-posta (PDF)',quiet:1,qFrom:'21:00',qTo:'08:00',goal:'20',weekend:1,breakRem:1,night:1,lang:'Türkçe',vtext:'Normal',tts:'Normal',contrast:0,twofa:0,share:1,navTopics:1},busy:[],read:[],chat:[],avatar:'#6D5BD0',prof:{phone:vPar().phone,email:vPar().email,contact:'Hafta içi 18:00–21:00',rel:vPar().rel}};save()}
const PS=()=>DB.par.settings;

/* ---------- bildirimler (öğrenci verisinden türetilir) ---------- */
function vNotifs(){const S=DB.st,out=[];const t=stuToday();
  S.plan.filter(p=>p.src==='Öğretmen'&&!p.exam&&p.d>=isoAdd(t,-3)&&p.d<=isoAdd(t,3)).forEach(p=>out.push({id:'na-'+p.id,type:'Yeni etkinlik',text:`Öğretmen “${p.title}” etkinliğini atadı (${fmtD(p.d)}).`,d:isoAdd(p.d,-1),to:'v-calisma/etkinlik'}));
  DB.exams.filter(x=>x.sections.includes(myStu().section)&&x.status==='Planlandı').forEach(x=>out.push({id:'ne-'+x.id,type:'Sınav',text:`${x.name} ${fmtDL(x.date)} tarihinde. ${daysBetween(t,x.date)} gün kaldı.`,d:isoAdd(t,-2),to:'v-sinav/yaklasan'}));
  S.reviews.filter(r=>r.status!=='Tamamlandı'&&r.due<=isoAdd(t,2)).forEach(r=>out.push({id:'nr-'+r.id,type:'Tekrar zamanı',text:`${kzOf(r.kz).topic} için kısa tekrar ${fmtD(r.due)} günü açılıyor.`,d:isoAdd(r.due,-1),to:'v-calisma/tekrar'}));
  S.products.filter(p=>prodStatus(p)==='Geri bildirim').forEach(p=>out.push({id:'nf-'+p.id,type:'Öğretmen geri bildirimi',text:`“${p.title}” ürünü değerlendirildi${p.score?` (${p.score} puan)`:''}.`,d:p.d||t,to:'v-calisma/studyo'}));
  BADGES.filter(b=>{const[a,n]=b.prog();return a>=n}).forEach(b=>out.push({id:'nb-'+b.id,type:'Rozet',text:`${vFirst()} “${b.t}” rozetini kazandı. Birlikte kutlayabilirsiniz!`,d:isoAdd(t,-1),to:'v-basari'}));
  out.push({id:'nw-'+vMon(),type:'Haftalık özet',text:`Geçen haftanın özeti hazır: ${S.prevWeeks[1].solved} soru, ${S.prevWeeks[1].mins} dakika çalışma.`,d:vMon(),to:'v-gelisim'});
  DB.errors.filter(e=>e.sid===ME&&e.evidence==='Güçlü').slice(0,1).forEach(e=>out.push({id:'nx-'+e.kz,type:'Dikkat gerektiren',text:`${kzOf(e.kz).topic} konusunda tekrarlayan bir zorluk gözlendi. Evde destek önerisi hazır.`,d:e.dates[e.dates.length-1]||t,to:'v-gelisim'}));
  return out.map(n=>({...n,read:DB.par.read.includes(n.id)})).sort((a,b)=>a.d<b.d?1:-1)}

/* ---------- menü ---------- */
const VNAV=[
 {grp:'Ana Navigasyon'},
 {id:'v-home',l:'Ana Sayfa',ic:'home'},
 {id:'v-ders',l:'Dersleri',ic:'book',subs:[['tum','Tüm Dersler'],['hafta','Bu Haftanın Aktiviteleri'],['program','Öğretim Programı']]},
 {id:'v-calisma',l:'Çalışma Alanı',ic:'clip',cnt:()=>DB.st.plan.filter(t=>!t.exam&&t.d<=stuToday()&&taskStatus(t)!=='Tamamlandı').length,cntL:'bekleyen görev',subs:[['etkinlik','Etkinlikler'],['tekrar','Tekrar Edilecekler'],['sifir','Sıfır Hata'],['studyo','Dijital Ürün Stüdyosu']]},
 {id:'v-sinav',l:'Sınavları',ic:'target',subs:[['yaklasan','Yaklaşan Sınavlar'],['sonuc','Sonuçlar']]},
 {id:'v-gelisim',l:'Gelişimi',ic:'chart'},
 {id:'v-plan',l:'Çalışma Planı',ic:'cal'},
 {id:'v-basari',l:'Başarıları',ic:'flag'},
 {grp:'AI',ai:1},
 {id:'v-navi',l:'Arkadaşım Navi',ic:'spark'},
 {grp:'Sistem'},
 {id:'v-bildirim',l:'Bildirimler',ic:'bell',cnt:()=>vNotifs().filter(n=>!n.read).length,cntL:'okunmamış'},
 {id:'v-ayarlar',l:'Ayarlar',ic:'sliders'},
 {id:'v-profil',l:'Profil',ic:'idcard'}
];
UI.vOpen=UI.vOpen||null;
parSidebar=function(){ensurePar();const s=myStu(),p=vPar();const ini=p.name.split(' ').map(x=>x[0]).join('').slice(0,2);
  let h=`<div class="side-hd"><div class="org"><div class="logo" aria-hidden="true">A</div><div><b>${TEACHER.orgShort}</b><small>${TEACHER.org}</small></div></div><div class="me"><div class="av" style="background:${DB.par.avatar};color:#fff">${ini}</div><div><b>${esc(p.name)}</b><small>Veli · ${p.rel}</small></div></div>
   <div class="vchild" title="Bağlı öğrenci"><span class="av" style="background:${DB.st.avatar}">EY</span><span class="sp"><b>${esc(fullName(s))}</b><small>${s.section} · bağlı öğrenci</small></span>${ic('lock',13)}</div></div><nav class="side-nav" aria-label="Veli menüsü">`;
  VNAV.forEach(n=>{if(n.grp){h+=`<div class="grp ${n.ai?'ai':''}">${n.grp}</div>`;return}
    const on=UI.route===n.id;const open=n.subs&&(UI.vOpen===n.id||(UI.vOpen===null&&on));const c=n.cnt?n.cnt():0;
    h+=`<button class="nv ${on?'on':''} ${open?'open':''}" data-act="vnav" data-v="${n.id}" ${on?'aria-current="page"':''} ${n.subs?`aria-expanded="${!!open}"`:''} ${UI.collapsed?`data-tip="${n.l}"`:''}>${ic(n.ic,19)}<span class="lbl">${n.l}</span>${c?`<span class="cnt" aria-label="${c} ${n.cntL}">${c}</span>`:''}${n.subs?ic('cd',15,'car'):''}</button>`;
    if(n.subs)h+=`<div class="sub ${open?'open':''}"><div>${n.subs.map(([s2,l])=>`<button class="${on&&UI.sub===s2?'on':''}" data-go="${n.id}/${s2}" tabindex="${open?0:-1}">${l}</button>`).join('')}</div></div>`});
  return h+`</nav><div class="side-ft"><span class="brand">Navig<span>AI</span>tor</span><button class="icb-s" data-act="collapse" aria-label="Menüyü daralt">${ic('panel',18)}</button></div>`};
/* yalnızca seçili grubun alt menüsü açık kalır */
ACT.vnav=el=>{const id=el.dataset.v;const n=VNAV.find(x=>x.id===id);if(n.subs&&UI.route===id){const open=UI.vOpen===id||(UI.vOpen===null);UI.vOpen=open?'':id;$('#side').innerHTML=sidebar();return}UI.vOpen=null;go(n.subs?id+'/'+n.subs[0][0]:id)};
parTop=function(P){const n=vNotifs().filter(x=>!x.read).length;const ini=vPar().name.split(' ').map(x=>x[0]).join('').slice(0,2);
  return `<button class="icb menu-btn" data-act="navOpen" aria-label="Menüyü aç">${ic('menu')}</button>
  <div class="ttl"><div class="crumb">${(P.crumbs||[]).map((c,i)=>i<P.crumbs.length-1?`<button data-go="${c[1]}">${esc(c[0])}</button>${ic('cr',12)}`:`<span>${esc(c[0])}</span>`).join('')}</div><h1 class="pt">${P.title}</h1></div>
  <span class="tpill" title="Bu panel yalnızca bağlı öğrencinizin verisini gösterir">${ic('lock',14)} ${esc(vFirst())} · ${myStu().section}</span>
  <button class="icb" data-go="v-bildirim" aria-label="Bildirimler, ${n} okunmamış">${ic('bell')}${n?`<span class="dot">${n}</span>`:''}</button>
  <button class="pf-btn" data-go="v-profil" aria-label="Profil"><span class="av" style="background:${DB.par.avatar}">${ini}</span><b>${esc(vPar().name.split(' ')[0])}</b></button>`};
const vCr=(...a)=>[['Ana Sayfa','v-home'],...a];

/* ---------- görselleştirme parçaları ---------- */
const vFlame=(n,size=64)=>`<svg viewBox="0 0 64 72" width="${size}" height="${size*72/64}" aria-hidden="true"><defs><linearGradient id="vfl" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="#FF5A1F"/><stop offset=".6" stop-color="#FF9F1C"/><stop offset="1" stop-color="#FFD84D"/></linearGradient></defs><path d="M32 4c4 12 18 18 18 36a18 18 0 0 1-36 0c0-10 6-14 8-20 2 6 4 8 6 10 0-12 2-18 4-26z" fill="url(#vfl)"/><path d="M32 34c2 6 8 8 8 16a8 8 0 0 1-16 0c0-4 3-6 4-9 1 2 2 3 3 4 0-5 0-8 1-11z" fill="#FFF3C4"/></svg>`;
function vRing(v,col='#2E9E6B',size=74){const r=30,C=2*Math.PI*r;return `<svg viewBox="0 0 74 74" width="${size}" height="${size}" aria-hidden="true"><circle cx="37" cy="37" r="${r}" fill="none" stroke="#EEE6DA" stroke-width="8"/><circle cx="37" cy="37" r="${r}" fill="none" stroke="${col}" stroke-width="8" stroke-linecap="round" stroke-dasharray="${C}" stroke-dashoffset="${C*(1-v/100)}" transform="rotate(-90 37 37)"/><text x="37" y="42" text-anchor="middle" font-size="16" font-weight="800" fill="#222" font-family="Nunito,Arial">%${v}</text></svg>`}
function vBars(vals,labels,col,unit=''){const mx=Math.max(...vals)||1;return `<div class="vbars">${vals.map((v,i)=>`<div class="vb"><b>${v}${unit}</b><span class="vbc"><i style="height:${Math.max(6,v/mx*100)}%;background:${i===vals.length-1?col:'#E3D8C8'}"></i></span><small>${labels[i]}</small></div>`).join('')}</div>`}
function vWeekDots(){const m=vMon();const set=new Set(DB.st.streak);if((DB.st.minutes[stuToday()]||0)+DB.st.secToday/60>=5)set.add(stuToday());return `<div class="vdots">${VDAYS.map((d,i)=>{const iso=isoAdd(m,i);const on=set.has(iso);const fut=iso>stuToday();return `<span class="${on?'on':''} ${fut?'fut':''}" title="${fmtD(iso)}"><i>${on?ic('check',11):''}</i>${d}</span>`}).join('')}</div>`}
function vPendViz(){const m=vMon();return `<div class="vdots pend">${VDAYS.map((d,i)=>{const iso=isoAdd(m,i);const ts=DB.st.plan.filter(t=>t.d===iso&&!t.exam);const left=ts.filter(t=>taskStatus(t)!=='Tamamlandı').length;return `<span class="${iso===stuToday()?'today':''}" title="${fmtD(iso)}: ${left} bekleyen"><i class="n${Math.min(left,3)}">${left||''}</i>${d}</span>`}).join('')}</div>`}
function vSkills(){const yet=c=>{const y=courseYet(c);return y?y.v:55};const d=digitalYet();return [
  ['Eleştirel düşünme',Math.round((yet('MAT')+yet('FEN'))/2),'Matematik ve Fen ölçümleri'],
  ['Problem çözme',yet('MAT'),'Matematik çözüm planı soruları'],
  ['Okuduğunu anlama',yet('TUR'),'Türkçe ölçümleri'],
  ['İletişim',yet('SOS'),'Sosyal Bilgiler · etkili iletişim'],
  ['Yaratıcılık',d?d.v:70,'Dijital Ürün Stüdyosu rubriği'],
  ['Dijital okuryazarlık',d?Math.min(100,d.v+4):68,'Dijital ürünler ve platform kullanımı'],
  ['Öz düzenleme',Math.min(100,Math.round(curStreak()/14*100)),'Çalışma serisi ve plan uyumu']]}
function vRadar(sk){const N=sk.length,cx=130,cy=120,R=88;const pt=(i,v)=>{const a=-Math.PI/2+i*2*Math.PI/N;return [cx+R*v/100*Math.cos(a),cy+R*v/100*Math.sin(a)]};
  let g='';[25,50,75,100].forEach(l=>{g+=`<polygon points="${sk.map((_,i)=>pt(i,l).join(',')).join(' ')}" fill="none" stroke="#EADFCF" stroke-width="1"/>`});
  sk.forEach((s,i)=>{const[x,y]=pt(i,100);const[lx,ly]=pt(i,122);g+=`<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" stroke="#EADFCF"/><text x="${lx}" y="${ly}" font-size="10.5" font-weight="700" text-anchor="${lx<cx-5?'end':lx>cx+5?'start':'middle'}" dominant-baseline="middle" fill="#4A3F35" font-family="Nunito,Arial">${s[0]}</text>`});
  return `<svg viewBox="-95 -10 450 265" class="vradar" role="img" aria-label="21. yüzyıl ve dijital beceriler profili">${g}<polygon points="${sk.map((s,i)=>pt(i,s[1]).join(',')).join(' ')}" fill="rgba(109,91,208,.22)" stroke="#6D5BD0" stroke-width="2.5" stroke-linejoin="round"/>${sk.map((s,i)=>{const[x,y]=pt(i,s[1]);return `<circle cx="${x}" cy="${y}" r="4" fill="#6D5BD0" stroke="#fff" stroke-width="1.5"/>`}).join('')}</svg>`}
const VTROPHY=`<svg viewBox="0 0 120 120" aria-hidden="true"><ellipse cx="60" cy="108" rx="34" ry="6" fill="rgba(0,0,0,.12)"/><path d="M38 20h44v22a22 22 0 0 1-44 0z" fill="#FFC531"/><path d="M38 26H24a12 12 0 0 0 14 18M82 26h14a12 12 0 0 1-14 18" fill="none" stroke="#FFC531" stroke-width="6"/><path d="M52 62h16v18H52z" fill="#E9A400"/><rect x="40" y="80" width="40" height="18" rx="5" fill="#8E5BD8"/><rect x="46" y="85" width="28" height="8" rx="3" fill="#B596F0"/><path d="M48 26c0 12 2 22 8 28" stroke="#FFE69A" stroke-width="5" stroke-linecap="round" fill="none"/><path d="m60 30 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z" fill="#fff"/><circle cx="18" cy="16" r="3" fill="#58CC9B"/><circle cx="104" cy="12" r="4" fill="#FF6B9E"/><circle cx="98" cy="60" r="3" fill="#5BB8F5"/><circle cx="14" cy="64" r="4" fill="#FFD84D"/></svg>`;
const vSrc=s=>`<span class="spill ${s==='Öğretmen'?'sp-teach':'sp-sys'}">${ic(s==='Öğretmen'?'user':'spark',12)} ${s==='Öğretmen'?'Öğretmen yönlendirmesi':'Sistem yönlendirmesi'}</span>`;
const vHomeIdea=kz=>{const k=kzOf(kz||'MAT7-4');const M={'MAT7-4':['Bir kâğıdı 4’e ve 5’e katlayıp birlikte 3/4 + 2/5’i modelleyin.','Mutfakta ölçü kaplarıyla “yarım + çeyrek” gibi toplamlar yapın.','Cevaptan önce “Paydalar eşit mi?” sorusunu sesli sorsun.'],'MAT7-3':['Evde bir sayı doğrusu çizip −2/3 ile −3/4’ü yerleştirin.','Termometre üzerinden eksi sayıları konuşun.','Hangisinin sıfıra daha uzak olduğunu kendisi açıklasın.'],'MAT7-2':['Alışveriş fişinde indirim ve borcu eksi sayıyla konuşun.','Çözümden sonra “işaret doğru mu?” kontrolünü birlikte yapın.','Hızlı değil, adım adım çözmesini övün.']};return {k,items:M[kz]||[`${k.topic} konusunu günlük hayattan bir örnekle konuşun.`,'10 dakikalık kısa çalışmalar yeterli.','Doğru cevaptan çok açıklamayı ve çabayı övün.']}};

/* ================= 1) ANA SAYFA ================= */
PAGES['v-home']=()=>{ensurePar();const s=myStu(),S=DB.st;const tt=DB.st.plan.filter(t=>t.d===stuToday()&&!t.exam);const left=tt.filter(t=>taskStatus(t)!=='Tamamlandı');const pend=S.plan.filter(t=>!t.exam&&t.d<=isoAdd(stuToday(),6)&&t.d>=vMon()&&taskStatus(t)!=='Tamamlandı');
  const acc=S.solvedWeek?Math.round(S.correctWeek/S.solvedWeek*100):0;const prevAcc=S.prevWeeks[1].acc;
  const ex=DB.exams.filter(x=>x.sections.includes(s.section)&&x.status==='Planlandı').sort((a,b)=>a.date<b.date?-1:1)[0];const last=myResults()[0];
  const daysW=VDAYS.filter((_,i)=>new Set(S.streak).has(isoAdd(vMon(),i))).length;const sugK=lastWeakKz();
  const pr=S.products.filter(p=>prodStatus(p)==='Geri bildirim').slice(-1)[0];
  return {title:'Ana Sayfa',crumbs:[['Ana Sayfa','v-home']],html:`
  <section class="vhero">${naviFig('welcome',170,'hb-navi')}<div class="hb-txt"><span class="eyebrow">${fmtDL(stuToday())} · ${TEACHER.org} · ${s.section}</span><h2 class="o-h" style="font-size:28px;margin:6px 0 8px">Merhaba ${esc(vHi())}! ${esc(s.first)} ${curStreak()} gündür kesintisiz çalışıyor.</h2>
   <div class="vchips"><span>${ic('clip',15)} Bugün <b>${left.length}</b> görev</span><span>${ic('clock',15)} <b>${left.reduce((a,t)=>a+t.mins,0)}</b> dk planlı</span>${ex?`<span>${ic('cal',15)} Sınava <b>${daysBetween(stuToday(),ex.date)}</b> gün</span>`:''}</div>
   <div class="row" style="margin-top:14px"><button class="btn pri" data-go="v-gelisim">${ic('chart',15)} Haftanın gelişimi</button></div></div></section>
  <div class="grid g4">
   <button class="vk" data-go="v-calisma/etkinlik" style="--vk:#FFF4DB"><span class="kl">${picon('cal','#FCEBC4',40)} Bekleyen etkinlik</span><span class="kn">${pend.length}<small> bu hafta</small></span>${vPendViz()}</button>
   <button class="vk" data-go="v-basari" style="--vk:#FFEBDD"><span class="kl">${picon('fire','#FBE3F1',40)} Öğrenme serisi</span><div class="row" style="flex-wrap:nowrap;gap:10px">${vFlame(curStreak(),46)}<span class="kn">${curStreak()}<small> gün</small></span></div>${vWeekDots()}</button>
   <button class="vk" data-go="v-gelisim" style="--vk:#E4F8EE"><span class="kl">${picon('list','#DDF5E8',40)} Bu hafta çözülen</span><span class="kn">${S.solvedWeek}<small> soru</small></span>${vBars([S.prevWeeks[0].solved,S.prevWeeks[1].solved,S.solvedWeek],['2 hf önce','Geçen hf','Bu hf'],'#2E9E6B')}</button>
   <button class="vk" data-go="v-gelisim" style="--vk:#E6EEFF"><span class="kl">${picon('shield','#E2EBFC',40)} İlk denemede doğruluk</span><div class="row" style="flex-wrap:nowrap;gap:12px">${vRing(acc,'#2F7DD8',70)}<span>${stars(acc)}<br><span class="small ${acc>=prevAcc?'up':'down'}">${acc>=prevAcc?'▲':'▼'} ${Math.abs(acc-prevAcc)} puan</span><br><span class="meta">geçen haftaya göre</span></span></div></button>
  </div>
  <div class="split2"><div class="col">
   <section class="ocard"><div class="card-hd"><div class="t"><h2 class="o-h">Bugünün yönlendirmeleri</h2><div class="meta">${esc(s.first)}’in bugünkü planı · öğretmen ve sistem yönlendirmeleri ayrı etiketlenir</div></div><button class="btn sm ghost" data-go="v-plan">Planı aç ${ic('cr',14)}</button></div>
    <div class="col" style="gap:8px">${tt.length?tt.map(t=>`<div class="trow">${cIcon(t.course,20)}<div class="sp" style="min-width:0"><b class="trunc" style="display:block">${esc(t.title)}</b><div class="row small muted" style="gap:8px;margin-top:3px"><span>${COURSE_UI[t.course].e}</span><span>${ic('clock',12)} ${t.mins} dk</span>${vSrc(t.src)}</div></div>${stPill(taskStatus(t))}</div>`).join(''):stateBox('empty','Bugün görev yok','')}</div></section>
   <section class="ocard"><div class="card-hd"><div class="t"><h2 class="o-h">Dersleri</h2><div class="meta">İçerik tamamlama (yolculuk) ve konu ustalığı ayrı gösterilir</div></div><button class="btn sm ghost" data-go="v-ders/tum">Tümü ${ic('cr',14)}</button></div>
    <div class="vcl">${Object.keys(COURSES).map(c=>{const y=courseYet(c);return `<button class="vcrow" data-go="v-ders/tum">${cIcon(c,18)}<span class="cn">${COURSE_UI[c].e}</span><span class="pbar"><i style="width:${cProg(c)}%;--c:${COURSE_UI[c].c}"></i></span><span class="small b">${durak(c)}</span><span class="small">${y?stars(y.v):'<span class="meta">yeni</span>'}</span></button>`}).join('')}</div></section>
   <section class="ocard"><div class="card-hd"><div class="t"><h2 class="o-h">Bu haftanın aktiviteleri</h2><div class="meta">${fmtD(vMon())} – ${fmtD(isoAdd(vMon(),6))}</div></div><button class="btn sm ghost" data-go="v-ders/hafta">Ayrıntı ${ic('cr',14)}</button></div>${vWeekStrip()}</section>
  </div><div class="col">
   <section class="ocard navi-card"><div class="row" style="align-items:flex-start;flex-wrap:nowrap">${navi('hint',72)}<div><h3 class="o-h" style="font-size:18px;margin:2px 0 6px">Navi’den öneri</h3><p class="small" style="margin:0">${sugK?`${esc(s.first)} <b>${esc(kzOf(sugK).topic)}</b> konusunda ${sugK==='MAT7-4'?'<b>payda eşitleme</b> adımında':'ilk adımda'} zorlanıyor olabilir. Çözümü değil, evde 10 dakikalık iki adımlık bir destek fikri hazırladım.`:'Bu hafta belirgin bir takılma görmedim. Düzenli çalışmasını övmeniz yeterli.'}</p></div></div>
    <div class="row" style="margin-top:12px"><button class="btn sm sec" data-act="vIdea" data-v="${sugK||'MAT7-4'}">${ic('bulb',14)} Evde destek fikri</button><button class="btn sm pri" data-go="v-navi">${ic('chat',14)} Navi’ye sor</button></div></section>
   <section class="ocard"><div class="card-hd"><div class="t"><h2 class="o-h">Sınavları</h2></div><button class="btn sm ghost" data-go="v-sinav/yaklasan">Tümü ${ic('cr',14)}</button></div>
    ${ex?`<div class="trow">${picon('cal','#FCEBC4',40)}<div class="sp"><b>${esc(ex.name)}</b><div class="small muted">${fmtDL(ex.date)} · ${daysBetween(stuToday(),ex.date)} gün kaldı</div></div><span class="spill sp-wait">Yaklaşan</span></div>`:''}
    ${last?`<button class="trow" style="width:100%;text-align:left;margin-top:8px" data-go="v-sinav/sonuc">${picon('shield','#E2EBFC',40)}<div class="sp"><b>Son sonuç: ${esc(last.name)}</b><div class="small muted">${last.c}/${last.n} doğru · ${fmtD(last.date)}</div></div>${vRing(Math.round(last.c/last.n*100),'#810000',52)}</button>`:''}
    <div class="meta" style="margin-top:10px">${ic('lock',12)} LGS formatlı denemeler 8. sınıfta açılır.</div></section>
   <section class="ocard"><h2 class="o-h">Öğretmen geri bildirimi</h2>${pr?`<div class="row" style="align-items:flex-start;flex-wrap:nowrap"><span class="avs">SY</span><div><b>${esc(pr.title)}</b>${pr.score?` · <span class="small">${stars(pr.score)}</span>`:''}<p class="small" style="margin:4px 0 0">${esc(pr.fb||'')}</p></div></div>`:stateBox('empty','Yeni geri bildirim yok','')}</section>
  </div></div>`}};
function vWeekStrip(){const m=vMon();return `<div class="vweek">${VDAYS.map((d,i)=>{const iso=isoAdd(m,i);const ts=DB.st.plan.filter(t=>t.d===iso);const busy=DB.par.busy.includes(iso);return `<div class="vwd ${iso===stuToday()?'today':''} ${busy?'busy':''}"><b>${d}</b><small>${fmtD(iso)}</small>${busy?`<span class="vbusy">${ic('house',11)} Aile</span>`:''}${ts.map(t=>{const st=taskStatus(t);return `<span class="vtk ${st==='Tamamlandı'?'ok':''}" style="--c:${t.exam?'#810000':SK_COL[t.course]||'#888'}" title="${esc(t.title)} · ${st}">${t.exam?ic('target',11):st==='Tamamlandı'?ic('check',11):''}${esc(t.title.split(/[·:]/)[0].trim())}</span>`}).join('')||'<span class="meta">—</span>'}</div>`}).join('')}</div>`}
ACT.vIdea=el=>{const I=vHomeIdea(el.dataset.v);openModal(()=>({title:'Evde destek fikri',sub:esc(I.k.topic)+' · 10 dakika',body:`<div class="row" style="align-items:flex-start;flex-wrap:nowrap">${naviFig('explain',140)}<div class="col" style="gap:8px">${I.items.map((t,i)=>bubble(`<b>${i+1}.</b> ${fracH(esc(t))}`)).join('')}<p class="meta" style="margin:0">Bu bir tanı değildir; öğretmenin paylaşımına açık kayıtlardan hazırlanan sade bir öneridir.</p></div></div>`,foot:`<button class="btn sec" data-act="closeLayer">Kapat</button><button class="btn pri" data-act="vIdeaPlan" data-v="${I.k.id}">${ic('cal',14)} Plana aile etkinliği olarak ekle</button>`}))};
ACT.vIdeaPlan=el=>{const k=kzOf(el.dataset.v);UI.modal=null;commit('Aile etkinliği Çalışma Planı’na eklendi',()=>{DB.st.plan.push({id:uid('pv'),title:'Evde birlikte: '+k.topic,course:k.course,mins:10,src:'Sistem',d:isoAdd(stuToday(),1),family:true})})};

/* ================= 2) DERSLERİ ================= */
PAGES['v-ders']=(sub)=>{const cr=l=>vCr(['Dersleri','v-ders/tum'],[l,'']);
  if(sub==='program')return {title:'Öğretim Programı',crumbs:cr('Öğretim Programı'),html:`<section class="ocard navi-card"><div class="row" style="flex-wrap:nowrap">${navi('present',56)}${bubble(`${esc(vFirst())}’in bu yıl öğreneceği her şey MEB’in resmi programında yazılı. “Sistemde” etiketi, ${esc(vFirst())}’in NavigAItor’da çalıştığı çıktıları gösterir.`)}</div></section>`+resmiView({grades:[myStu().grade||7],c:'MAT',cls:'ocard'})};
  if(sub==='hafta'){const m=vMon();const ts=DB.st.plan.filter(t=>t.d>=m&&t.d<=isoAdd(m,6));const done=ts.filter(t=>taskStatus(t)==='Tamamlandı').length;
    return {title:'Bu Haftanın Aktiviteleri',crumbs:cr('Bu Haftanın Aktiviteleri'),html:`<section class="ocard"><div class="row"><div class="sp"><h2 class="o-h">${fmtD(m)} – ${fmtD(isoAdd(m,6))}</h2><div class="meta">${done}/${ts.length} aktivite tamamlandı</div></div><div class="legend">${Object.keys(COURSES).map(c=>`<span><span class="sw" style="background:${SK_COL[c]}"></span>${COURSE_UI[c].e}</span>`).join('')}</div></div><div class="pbar" style="margin:10px 0 14px"><i style="width:${ts.length?done/ts.length*100:0}%;--c:#2E9E6B"></i></div>${vWeekStrip()}</section>
     <section class="ocard"><h2 class="o-h">Aktivite listesi</h2><div class="col" style="gap:8px">${ts.sort((a,b)=>a.d<b.d?-1:1).map(t=>`<div class="trow">${cIcon(t.course,18)}<div class="sp" style="min-width:0"><b class="trunc" style="display:block">${esc(t.title)}</b><div class="row small muted" style="gap:8px;margin-top:3px"><span>${ic('cal',12)} ${fmtDL(t.d)}</span><span>${ic('clock',12)} ${t.mins} dk</span>${t.exam?'':vSrc(t.src)}</div></div>${stPill(taskStatus(t))}</div>`).join('')}</div></section>`}}
  return {title:'Tüm Dersler',crumbs:cr('Tüm Dersler'),html:`<div class="grid g3">${Object.keys(COURSES).map(c=>{const y=courseYet(c);const g=CGRAD[c];const ks=KZ.filter(k=>k.course===c&&k.grade===7);const open=UI.exp['vd'+c];const wk=DB.st.log.filter(l=>l.course===c&&l.d>=vMon()).reduce((a,l)=>a+l.mins,0);
    return `<section class="vcc"><div class="vcc-h" style="--g1:${g[0]};--g2:${g[1]}">${cIcon(c,26)}<div class="sp"><b>${COURSE_UI[c].e}</b><small>${COURSES[c].teacher}</small></div></div><div class="vcc-b">
     <div class="row small"><span class="sp">İçerik yolculuğu</span><b>${durak(c)}</b></div><div class="pbar"><i style="width:${cProg(c)}%;--c:${g[0]}"></i></div>
     <div class="row small" style="margin-top:10px"><span class="sp">Konu ustalığı</span>${y?lvTag(y.v):'<span class="meta">Henüz ölçüm yok</span>'}</div>
     <div class="row small muted" style="margin-top:8px;gap:12px"><span>${ic('book',12)} Son: ${COURSE_PROG[c].last}</span><span>${ic('clock',12)} Bu hafta ${wk} dk</span></div>
     <button class="lnk small" style="margin-top:10px" data-act="vExp" data-v="vd${c}" aria-expanded="${!!open}">${open?'Konuları gizle':'Konuları göster ('+ks.length+')'}</button>
     ${open?`<div class="col" style="gap:6px;margin-top:8px">${ks.map(k=>{const m=mOf(ME,k.id);return `<div class="row small vtopic"><span class="sp">${esc(k.topic)}</span>${m?stars(m.v):'<span class="meta">yeni</span>'}</div>`}).join('')}</div>`:''}</div></section>`}).join('')}</div>`}};
ACT.vExp=el=>{UI.exp[el.dataset.v]=!UI.exp[el.dataset.v];render()};

/* ================= 3) ÇALIŞMA ALANI ================= */
PAGES['v-calisma']=(sub)=>{const S=DB.st;const cr=l=>vCr(['Çalışma Alanı','v-calisma/etkinlik'],[l,'']);
  if(sub==='tekrar'){const rs=S.reviews;return {title:'Tekrar Edilecekler',crumbs:cr('Tekrar Edilecekler'),html:`<section class="ocard navi-card"><div class="row" style="flex-wrap:nowrap">${navi('review',60)}${bubble(`${esc(vFirst())}’in tekrarları aralıklı planlanır: <b>1 hafta → 2 hafta → 1 ay</b>. Tekrar günü geldiğinde size de bildirim gelir.`)}</div></section><div class="grid g2">${rs.map(r=>`<section class="ocard"><div class="row">${cIcon(kzOf(r.kz).course,20)}<div class="sp"><b>${esc(kzOf(r.kz).topic)}</b><div class="meta">aralık: ${r.interval}</div></div>${stPill(r.status==='Tamamlandı'?'Tamamlandı':'Bekliyor')}</div><p class="small" style="margin:10px 0 4px"><b>İhtiyaç:</b> ${esc(r.need)}</p><div class="row small muted"><span class="sp">${ic('cal',12)} Tekrar günü: <b>${fmtDL(r.due)}</b></span></div></section>`).join('')||stateBox('empty','Tekrar yok','')}</div>`}}
  if(sub==='sifir'){const zs=S.zero;return {title:'Sıfır Hata',crumbs:cr('Sıfır Hata'),html:`<section class="ocard"><p class="small" style="margin:0 0 10px">Sıfır Hata, aynı kazanımdan hatasız bir set tamamlanana kadar süren kısa bir moddur. Tek hata seriyi sıfırlar; amaç dikkatli çalışmayı alışkanlık hâline getirmektir.</p><div class="col" style="gap:8px">${zs.map(z=>`<div class="trow">${cIcon(kzOf(z.kz).course,18)}<div class="sp"><b>${esc(z.title)}</b><div class="meta">${esc(kzOf(z.kz).topic)} · ${fmtD(z.date)}</div></div><span class="spill ${z.done?'sp-done':'sp-go'}">${z.res||''} ${z.done?'Tamamlandı':'Devam ediyor'}</span></div>`).join('')||stateBox('empty','Henüz Sıfır Hata seti yok','')}</div></section>`}}
  if(sub==='studyo'){return {title:'Dijital Ürün Stüdyosu',crumbs:cr('Dijital Ürün Stüdyosu'),html:`<div class="grid g3">${S.products.map(p=>{const st=prodStatus(p);const a=p.act&&DB.acts.find(x=>x.id===p.act);const sb=a&&a.subs[ME];const fb=sb&&sb.evaluated?sb.fb:p.fb;const sc=sb&&sb.evaluated?sb.score:p.score;
     return `<section class="ocard vprod"><button class="vthumb" data-act="vProd" data-v="${p.id}" aria-label="${esc(p.title)} önizle">${thumbOf(p)}</button><div class="row" style="margin-top:10px"><b class="sp">${esc(p.title)}</b><span class="spill ${st==='Geri bildirim'?'sp-done':st==='Değerlendiriliyor'?'sp-eval':'sp-wait'}">${st}</span></div><div class="meta">${esc(p.type||'İnfografik')} · ${COURSE_UI[p.course||'MAT'].e}</div>${fb?`<div class="bubble b-right" style="margin-top:10px"><b>Öğretmen:</b> ${esc(fb)}${sc?`<div class="small" style="margin-top:4px">${stars(sc)} ${LVL(sc)[0]}</div>`:''}</div>`:`<p class="small muted" style="margin:10px 0 0">${st==='Bekliyor'?'Henüz teslim edilmedi.':'Öğretmen değerlendirmesi bekleniyor.'}</p>`}</section>`}).join('')}</div>`}}
  const f=UI.vf||'';const list=S.plan.filter(t=>!t.exam).filter(t=>!f||(f==='bek'?taskStatus(t)!=='Tamamlandı':taskStatus(t)==='Tamamlandı')).sort((a,b)=>a.d<b.d?-1:1);
  return {title:'Etkinlikler',crumbs:cr('Etkinlikler'),html:`<section class="ocard" style="padding:12px 16px"><div class="row"><div class="seg">${[['','Tümü'],['bek','Bekleyen'],['tam','Tamamlanan']].map(([k,l])=>`<button class="${f===k?'on':''}" data-act="vf" data-v="${k}">${l}</button>`).join('')}</div><span class="sp"></span><span class="small muted">${list.length} etkinlik · salt okunur görünüm</span></div></section>
   <div class="ggrid">${list.map(t=>{const k=GK(t);const st=taskStatus(t);const d=t.sim?S.doneSets[t.sim]:t.set?S.doneSets[t.set]:null;return `<article class="gcard ${st==='Tamamlandı'?'is-done':''}" style="--g1:${k.g[0]};--g2:${k.g[1]}"><div class="gc-art">${ART[k.art]}<span class="gc-kind">${ic(k.ic,12)} ${k.k}</span>${st==='Tamamlandı'?`<span class="gc-done">${ic('check',18)}</span>`:''}</div><div class="gc-b"><div class="row small muted" style="gap:8px">${cIcon(t.course,16)}<span>${COURSE_UI[t.course].e}</span><span>${ic('clock',12)} ${t.mins} dk</span><span>${ic('cal',12)} ${fmtD(t.d)}</span></div><b class="gc-t">${esc(t.title)}</b><div class="row" style="gap:6px">${vSrc(t.src)}${stPill(st)}</div>${d?`<div class="small">Sonuç: <b>${d.c}/${d.n}</b> ${d.score?stars(d.score):''}</div>`:''}<div class="gc-f"><button class="btn sm sec" data-act="vTask" data-v="${t.id}">Ayrıntı ${ic('cr',14)}</button></div></div></article>`}).join('')||stateBox('none','Etkinlik yok','')}</div>`}};
ACT.vf=el=>{UI.vf=el.dataset.v;render()};
ACT.vTask=el=>{const t=DB.st.plan.find(x=>x.id===el.dataset.v);const st=taskStatus(t);const d=t.sim?DB.st.doneSets[t.sim]:t.set?DB.st.doneSets[t.set]:null;const sim=t.sim&&SIMS[t.sim];const kz=sim?sim.kz:(getSet(t.set)||{}).kz;const I=kz?vHomeIdea(kz):null;
  openDrawer(()=>({eyebrow:COURSE_UI[t.course].e+' · '+(t.src==='Öğretmen'?'Öğretmen yönlendirmesi':'Sistem yönlendirmesi'),title:esc(t.title),body:`<div class="row">${stPill(st)}<span class="spill sp-wait">${ic('cal',12)} ${fmtDL(t.d)}</span><span class="spill sp-wait">${ic('clock',12)} ${t.mins} dk</span></div>
   ${sim?`<p>${esc(sim.desc)}</p><p class="small muted">Bu etkinlik etkileşimli bir ${sim.kind.toLocaleLowerCase('tr')}dur; ${esc(vFirst())} deneyerek keşfeder.</p>`:''}${kz?`<p class="small"><b>Konu:</b> ${esc(kzOf(kz).topic)}</p>`:''}
   ${d?`<section class="ocard" style="padding:14px"><b>Sonuç</b><div class="row" style="margin-top:6px">${vRing(Math.round(d.c/d.n*100),'#2E9E6B',60)}<span>${d.c}/${d.n} doğru<br>${fmtDL(d.date)}</span></div></section>`:''}
   ${I?`<h3 class="o-h" style="font-size:16px;margin-top:12px">Evde nasıl destek olabilirsiniz?</h3><ul class="small">${I.items.slice(0,2).map(x=>`<li>${fracH(esc(x))}</li>`).join('')}</ul>`:''}`}))};
ACT.vProd=el=>{const p=DB.st.products.find(x=>x.id===el.dataset.v);openModal(()=>({title:esc(p.title),sub:esc(p.type||'Ürün'),body:`<div style="max-width:520px;margin:0 auto" class="vthumb big">${thumbOf(p)}</div>`,foot:`<button class="btn pri" data-act="closeLayer">Kapat</button>`}),true)};

/* ================= 4) SINAVLARI ================= */
PAGES['v-sinav']=(sub)=>{const s=myStu();const cr=l=>vCr(['Sınavları','v-sinav/yaklasan'],[l,'']);
  if(sub==='sonuc'){const rs=myResults();if(!rs.length)return {title:'Sonuçlar',crumbs:cr('Sonuçlar'),html:stateBox('empty','Henüz sonuç yok','')};const cur=rs.find(r=>r.id===UI.rsel)||rs[0];UI.rsel=cur.id;const pc=Math.round(cur.c/cur.n*100);const prev=rs.filter(r=>r.date<cur.date)[0];const it=DB.items[cur.id];const byK={};it.forEach(q=>{(byK[q.kz]=byK[q.kz]||{n:0,c:0}).n++;if(q.resp[ME].c===q.correct)byK[q.kz].c++});const weak=Object.entries(byK).filter(([k,v])=>v.c/v.n<.6).map(([k])=>k);
    return {title:'Sonuçlar',crumbs:cr('Sonuçlar'),html:`<div class="split-l"><section class="ocard" style="padding:10px">${rs.map(r=>`<button class="thread ${r.id===cur.id?'on':''}" data-act="rPick" data-v="${r.id}">${cIcon('MAT',16)}<span class="sp"><b class="small">${esc(r.name)}</b><br><span class="meta">${fmtD(r.date)}</span></span><b class="small">${r.c}/${r.n}</b></button>`).join('')}</section>
     <div class="col"><section class="ocard"><div class="row"><div class="sp"><div class="eyebrow">${fmtDL(cur.date)}</div><h2 class="o-h">${esc(cur.name)}</h2><div class="small muted">${prev?(pc>Math.round(prev.c/prev.n*100)?'Önceki sınava göre yükseldi ▲':pc===Math.round(prev.c/prev.n*100)?'Önceki sınavla aynı':'Önceki sınavın biraz gerisinde ▼'):'İlk sınav'} · sınıf sıralaması gösterilmez</div></div>${vRing(pc,'#810000',84)}</div>
      <div class="dyb" role="img" aria-label="${cur.c} doğru, ${cur.w} yanlış, ${cur.b} boş" style="margin-top:12px"><i style="flex:${cur.c};background:#2E9E6B"></i><i style="flex:${cur.w||0.001};background:#810000"></i><i style="flex:${cur.b||0.001};background:#C9C2B6"></i></div><div class="legend" style="margin-top:6px"><span><span class="sw" style="background:#2E9E6B"></span>Doğru ${cur.c}</span><span><span class="sw" style="background:#810000"></span>Yanlış ${cur.w}</span><span><span class="sw" style="background:#C9C2B6"></span>Boş ${cur.b}</span></div>
      <h3 class="o-h" style="font-size:16px;margin:16px 0 8px">Konu kırılımı</h3><div class="mini-bars">${Object.entries(byK).map(([k,v])=>`<div class="mb"><span class="small trunc">${esc(kzOf(k).topic)}</span><span class="pbar"><i style="width:${v.c/v.n*100}%;--c:${v.c/v.n>=.6?'#2E9E6B':'#E0A04B'}"></i></span><b class="small">${v.c}/${v.n}</b></div>`).join('')}</div></section>
      <section class="ocard navi-card"><div class="row" style="align-items:flex-start;flex-wrap:nowrap">${navi('explain',60)}<div><b>Evde ne yapılabilir?</b><p class="small" style="margin:4px 0 0">${weak.length?`${weak.map(k=>esc(kzOf(k).topic)).join(', ')} konularında kısa tekrar faydalı olur. Sistem bu konular için tekrar planladı; sizin rolünüz düzenli olmasını desteklemek.`:'Tüm konularda dengeli bir sonuç. Çabasını övmeniz yeterli.'}</p>${weak[0]?`<button class="btn sm sec" style="margin-top:8px" data-act="vIdea" data-v="${weak[0]}">${ic('bulb',14)} Evde destek fikri</button>`:''}</div></div></section></div></div>`}}
  const ex=DB.exams.filter(x=>x.sections.includes(s.section)&&x.status==='Planlandı').concat(DB.tests.filter(t=>t.sections.includes(s.section)&&t.status==='Planlandı'));
  return {title:'Yaklaşan Sınavlar',crumbs:cr('Yaklaşan Sınavlar'),html:`<div class="col" style="gap:12px">${ex.sort((a,b)=>a.date<b.date?-1:1).map(x=>{const prep=DB.st.plan.filter(p=>p.prep===x.id);const pd=prep.filter(p=>taskStatus(p)==='Tamamlandı').length;const left=daysBetween(stuToday(),x.date);
    return `<section class="ocard"><div class="row">${picon('cal','#FCEBC4',52)}<div class="sp"><div class="eyebrow">${x.kind||'Yazılı sınav'} · ${COURSES[x.course||'MAT'].name}</div><h3 class="o-h" style="font-size:19px;margin:2px 0">${esc(x.name)}</h3><div class="small muted">${fmtDL(x.date)} · ${left>0?left+' gün kaldı':'bugün'}${x.dur?' · '+x.dur+' dakika':''}</div></div><div class="vcount"><b>${left}</b><small>gün</small></div></div>
     <div class="row" style="gap:6px;margin-top:12px">${x.kz.map(k=>{const m=mOf(ME,k);return `<span class="spill ${m&&m.v>=70?'sp-done':m?'sp-go':'sp-wait'}">${esc(kzOf(k).topic)}${m?' · '+LVL(m.v)[0]:''}</span>`}).join('')}</div>
     <div class="row small" style="margin-top:12px"><span class="sp">${prep.length?`Hazırlık planı: <b>${pd}/${prep.length}</b> görev tamamlandı`:'Hazırlık görevi henüz plana eklenmedi.'}</span>${prep.length?'':`<button class="btn sm sec" data-act="vPrep" data-v="${x.id}">${ic('send',14)} ${esc(vFirst())}’e hazırlık öner</button>`}</div></section>`}).join('')||stateBox('empty','Yaklaşan sınav yok','')}
   <section class="ocard lgs"><div class="row">${ic('lock',18)}<div class="sp"><b>LGS formatı · 25 soru</b><div class="small muted">Yalnızca 8. sınıf öğrencileri için açılır. ${esc(vFirst())} 7. sınıfta.</div></div></div></section></div>`}};
ACT.vPrep=el=>{const x=[...DB.exams,...DB.tests].find(e=>e.id===el.dataset.v);commit(`Hazırlık önerisi ${vFirst()}’in planına eklendi`,()=>{x.kz.slice(0,3).forEach((k,i)=>{const set=makeGenSet(k,4,{title:'Hazırlık: '+kzOf(k).topic,mode:'practice'});DB.st.plan.push({id:uid('p'),title:'Sınav hazırlığı: '+kzOf(k).topic,course:'MAT',mins:8,src:'Sistem',d:isoAdd(stuToday(),2+i*2),set,prep:x.id})});DB.st.notifs.unshift({id:uid('sn'),type:'Sınav',text:'Velin sınav hazırlığı önerdi; görevler planına eklendi.',d:stuToday(),read:false,to:'o-plan'})})};

/* ================= 5) GELİŞİMİ (tek sayfa) ================= */
PAGES['v-gelisim']=()=>{const S=DB.st;const ks=Object.keys(DB.measures[ME]).map(k=>({k:kzOf(k),m:mOf(ME,k)}));
  const wk=[...S.prevWeeks,{w:'Bu hafta',solved:S.solvedWeek,acc:S.solvedWeek?Math.round(S.correctWeek/S.solvedWeek*100):0,mins:Math.round(Object.entries(S.minutes).reduce((a,[d,m])=>a+(d>=vMon()?m:0),0)+S.secToday/60)}];
  const gAll=ks.filter(x=>x.m.v>=72&&x.m.n>=2).sort((a,b)=>b.m.v-a.m.v);const g=UI.vgAll?gAll:gAll.slice(0,5);const w=ks.filter(x=>x.m.v<68).sort((a,b)=>a.m.v-b.m.v);const sk=vSkills();
  return {title:'Gelişimi',crumbs:vCr(['Gelişimi','']),html:`
  <section class="ocard navi-card"><div class="row" style="flex-wrap:nowrap">${navi('review',60)}${bubble(`${esc(vFirst())} burada yalnızca <b>kendi önceki haftalarıyla</b> karşılaştırılır; sınıf sıralaması yoktur. Kayıtlar bir tanı değil, destek için yol göstericidir.`)}</div></section>
  <div class="grid g3">
   <section class="ocard"><h3 class="o-h" style="font-size:17px">Çözülen soru</h3>${vBars(wk.map(x=>x.solved),wk.map(x=>x.w.replace(' (bu hafta)','')),'#810000')}</section>
   <section class="ocard"><h3 class="o-h" style="font-size:17px">İlk denemede doğru</h3>${vBars(wk.map(x=>x.acc),wk.map(x=>x.w),'#2E9E6B','%')}</section>
   <section class="ocard"><h3 class="o-h" style="font-size:17px">Çalışma süresi</h3>${vBars(wk.map(x=>x.mins),wk.map(x=>x.w),'#E0A04B',' dk')}</section></div>
  <div class="grid g2">
   <section class="ocard"><h2 class="o-h">${ic('okc',18)} Güçlü yönleri</h2><div class="meta" style="margin-bottom:8px">En az iki ölçümle kanıtlanan alanlar</div><div class="col" style="gap:8px">${g.map(x=>`<div class="trow">${cIcon(x.k.course,18)}<div class="sp"><b class="small">${esc(x.k.topic)}</b><div class="meta">${COURSE_UI[x.k.course].e} · ${x.m.n} ölçüm · beceri: ${x.k.skill}</div></div>${lvTag(x.m.v)}</div>`).join('')||stateBox('ins','Henüz yeterli kanıt yok','')}${gAll.length>5?`<button class="lnk small" data-act="vgAll">${UI.vgAll?'Daha az göster':'Tümünü göster ('+gAll.length+')'}</button>`:''}</div></section>
   <section class="ocard"><h2 class="o-h">${ic('target',18)} Geliştirilecek alanlar</h2><div class="meta" style="margin-bottom:8px">Her biri için evde 10 dakikalık destek fikri</div><div class="col" style="gap:8px">${w.map(x=>`<div class="trow">${cIcon(x.k.course,18)}<div class="sp"><b class="small">${esc(x.k.topic)}</b><div class="meta">${x.m.n<2?'Yetersiz veri · takip ediliyor':LVL(x.m.v)[0]}</div></div><button class="btn xs sec" data-act="vIdea" data-v="${x.k.id}">${ic('bulb',12)} Fikir</button></div>`).join('')||stateBox('empty','Öncelikli alan yok','')}</div></section></div>
  <section class="ocard"><div class="card-hd"><div class="t"><h2 class="o-h">21. yüzyıl ve dijital beceriler</h2><div class="meta">Ders ölçümleri, Dijital Ürün Stüdyosu rubriği ve çalışma düzeninden türetilen demo profil</div></div></div>
   <div class="vskill">${vRadar(sk)}<div class="col" style="gap:8px">${sk.map(x=>`<div class="row small vsk"><span class="sp"><b>${x[0]}</b><br><span class="meta">${x[2]}</span></span>${lvTag(x[1])}</div>`).join('')}</div></div></section>
  <section class="ocard"><h2 class="o-h">Ders bazında ustalık</h2><div class="mini-bars">${Object.keys(COURSES).map(c=>{const y=courseYet(c);return `<div class="mb"><span class="small">${COURSE_UI[c].e}</span><span class="pbar"><i style="width:${y?y.v:0}%;--c:${SK_COL[c]}"></i></span><span class="small">${y?stars(y.v):'—'}</span></div>`}).join('')}</div></section>`}};

/* ================= 6) ÇALIŞMA PLANI (takvim + Navi yöntemleri) ================= */
const VMETHODS=[
 {id:'kisa',t:'Kısa ve sık çalışma',ic:'clock',c:'#2F7DD8',why:'Beyin kısa bloklarda daha iyi odaklanır. 15–20 dakikalık çalışma + 5 dakika mola.',fit:()=>`${vFirst()} bu hafta ortalama ${Math.round((DB.st.prevWeeks[1].mins)/7)} dk/gün çalıştı. Günlük hedef: ${PS().goal} dk.`,task:{title:'Odak bloğu: 20 dk + mola',mins:20}},
 {id:'aralik',t:'Aralıklı tekrar',ic:'repeat',c:'#12A39A',why:'Öğrenilen konu 1 hafta → 2 hafta → 1 ay arayla tekrar edilince kalıcı olur.',fit:()=>{const r=DB.st.reviews.filter(x=>x.status!=='Tamamlandı');return r.length?`Bu hafta ${r.length} tekrar planlı: ${r.map(x=>kzOf(x.kz).topic).join(', ')}.`:'Bu hafta planlı tekrar yok.'},task:{title:'Tekrar: geçen haftanın konusu',mins:10}},
 {id:'karisik',t:'Karışık pratik',ic:'layers',c:'#7B5CFA',why:'Farklı soru türlerini karıştırmak, hangi yöntemi seçeceğini öğrenmeyi güçlendirir.',fit:()=>'Kesirler, tam sayılar ve denklemlerden karışık 6 soruluk bir set önerilir.',task:{title:'Karışık pratik: 6 soru',mins:10}},
 {id:'anlat',t:'Bana anlat (öğreterek öğren)',ic:'chat',c:'#E07A2F',why:'Çocuğun öğrendiğini size anlatması, eksik yerleri görünür kılar.',fit:()=>`Akşam yemeğinden sonra ${vFirst()}’in “bugün ne öğrendim?” sorusuna 3 dakika cevap vermesi yeterli.`,task:{title:'Bana anlat: bugün ne öğrendim?',mins:5}},
 {id:'sinav',t:'Sınava geri sayım',ic:'target',c:'#810000',why:'Sınavdan 14 gün önce başlayan küçük hazırlık adımları son gün yoğunluğunu önler.',fit:()=>{const ex=DB.exams.find(x=>x.sections.includes(myStu().section)&&x.status==='Planlandı');return ex?`${ex.name} için ${daysBetween(stuToday(),ex.date)} gün var; haftada 3 hazırlık görevi önerilir.`:'Yaklaşan sınav yok.'},task:{title:'Sınav hazırlığı: kısa deneme',mins:15}}
];
PAGES['v-plan']=()=>{ensurePar();const view=UI.vpv||'hafta';const off=UI.vpo||0;const m=isoAdd(vMon(),off*7);const S=DB.st;
  const dayTasks=iso=>S.plan.filter(t=>t.d===iso);const goal=+PS().goal;
  const cal=view==='hafta'?`<div class="vcal">${VDAYS.map((d,i)=>{const iso=isoAdd(m,i);const ts=dayTasks(iso);const mins=ts.filter(t=>!t.exam).reduce((a,t)=>a+t.mins,0);const busy=DB.par.busy.includes(iso);const over=mins>goal;
     return `<div class="vcd ${iso===stuToday()?'today':''} ${busy?'busy':''}"><div class="vcd-h"><b>${d}</b><span>${fmtD(iso)}</span></div><div class="vload ${over?'over':''}" title="${mins} dk / hedef ${goal} dk"><i style="width:${Math.min(100,mins/goal*100)}%"></i></div><small class="${over?'warn':'meta'}">${mins} dk${over?' · hedefin üstünde':''}</small>
      ${busy?`<div class="vfam">${ic('house',13)} Aile zamanı</div>`:''}
      ${ts.map(t=>`<div class="vblk ${taskStatus(t)==='Tamamlandı'?'ok':''} ${t.family?'fam':''}" style="--c:${t.exam?'#810000':SK_COL[t.course]}"><b>${esc(t.title)}</b><small>${t.exam?'Sınav':t.family?'Aile etkinliği':(t.src==='Öğretmen'?'Öğretmen':'Sistem')+' · '+t.mins+' dk'}</small></div>`).join('')}
      <button class="lnk small" data-act="vBusy" data-v="${iso}">${busy?'Aile zamanını kaldır':'+ Aile zamanı ekle'}</button></div>`}).join('')}</div>`
   :`<div class="vmonth">${VDAYS.map(d=>`<b>${d}</b>`).join('')}${Array.from({length:35},(_,i)=>{const iso=isoAdd(isoAdd(vMon(),-7),i+off*28);const ts=dayTasks(iso);return `<div class="vmd ${iso===stuToday()?'today':''} ${DB.par.busy.includes(iso)?'busy':''}"><span>${+iso.slice(8)}</span><div>${ts.slice(0,4).map(t=>`<i style="background:${t.exam?'#810000':SK_COL[t.course]}" title="${esc(t.title)}"></i>`).join('')}</div>${ts.some(t=>t.exam)?`<em>Sınav</em>`:''}</div>`}).join('')}</div>`;
  return {title:'Çalışma Planı',crumbs:vCr(['Çalışma Planı','']),html:`
  <section class="ocard"><div class="row"><div class="seg">${[['hafta','Hafta'],['ay','Ay']].map(([k,l])=>`<button class="${view===k?'on':''}" data-act="vpv" data-v="${k}">${l}</button>`).join('')}</div><button class="icb" data-act="vpo" data-v="-1" aria-label="Önceki">${ic('cl')}</button><b>${view==='hafta'?`${fmtD(m)} – ${fmtD(isoAdd(m,6))}`:'4 haftalık görünüm'}</b><button class="icb" data-act="vpo" data-v="1" aria-label="Sonraki">${ic('cr')}</button><span class="sp"></span><button class="btn sm sec" data-act="vpo0">Bugün</button><button class="btn sm pri" data-act="vBalance">${ic('spark',14)} Navi ile planı dengele</button></div>
   <div class="meta" style="margin:8px 0 12px">Çubuk: günlük çalışma yükü / hedef (${goal} dk, Ayarlar’dan değişir) · “Aile zamanı” eklediğiniz günlere Navi sistem görevi koymaz.</div>${cal}</section>
  <div class="split2"><section class="ocard"><div class="card-hd"><div class="t"><h2 class="o-h">Navi’nin önerdiği çalışma yöntemleri</h2><div class="meta">Yapay zekâ destekli öneriler ${esc(vFirst())}’in verisine göre kişiselleşir (demo kurallı yanıt)</div></div></div>
   <div class="vmeth">${VMETHODS.map(x=>`<div class="vm" style="--c:${x.c}"><span class="vm-i">${ic(x.ic,20)}</span><div class="sp"><b>${x.t}</b><p class="small" style="margin:4px 0">${x.why}</p><p class="small vm-fit">${ic('spark',12)} ${esc(x.fit())}</p></div><button class="btn sm sec" data-act="vMeth" data-v="${x.id}">${ic('send',13)} Öner</button></div>`).join('')}</div></section>
   <section class="ocard"><h2 class="o-h">Verimli saatleri</h2><div class="meta" style="margin-bottom:10px">Son 3 haftadaki çalışma kayıtlarından (demo)</div>${vHours()}<div class="bubble" style="margin-top:12px">${navi('plan',28)} ${esc(vFirst())} en çok <b>17:00–19:00</b> arasında odaklanıyor. Ödev saatini bu aralığa koymak iyi olur.</div></section></div>`}};
function vHours(){const H=[['15',2],['16',5],['17',9],['18',8],['19',5],['20',3],['21',1]];return `<div class="vhrs">${H.map(([h,v])=>`<div><i style="height:${v*10}%;opacity:${.35+v/14}"></i><small>${h}:00</small></div>`).join('')}</div>`}
ACT.vpv=el=>{UI.vpv=el.dataset.v;UI.vpo=0;render()};ACT.vpo=el=>{UI.vpo=(UI.vpo||0)+ +el.dataset.v;render()};ACT.vpo0=()=>{UI.vpo=0;render()};
ACT.vBusy=el=>{const iso=el.dataset.v;const has=DB.par.busy.includes(iso);commit(has?'Aile zamanı kaldırıldı':`Aile zamanı eklendi · ${fmtD(iso)} günündeki sistem görevleri ertelendi`,()=>{if(has){DB.par.busy=DB.par.busy.filter(x=>x!==iso);return}DB.par.busy.push(iso);DB.st.plan.filter(t=>t.d===iso&&t.src==='Sistem'&&!t.fixed&&!t.exam&&taskStatus(t)!=='Tamamlandı').forEach(t=>{let d=isoAdd(iso,1);while(DB.par.busy.includes(d))d=isoAdd(d,1);t.d=d})})};
ACT.vBalance=()=>{const goal=+PS().goal;let moved=0;commit('Plan dengelendi',()=>{const m=isoAdd(vMon(),(UI.vpo||0)*7);for(let i=0;i<7;i++){const iso=isoAdd(m,i);const ts=DB.st.plan.filter(t=>t.d===iso&&!t.exam);let mins=ts.reduce((a,t)=>a+t.mins,0);ts.filter(t=>t.src==='Sistem'&&!t.fixed&&taskStatus(t)!=='Tamamlandı').forEach(t=>{if(mins<=goal)return;for(let j=1;j<7;j++){const d=isoAdd(iso,j);if(DB.par.busy.includes(d))continue;const dm=DB.st.plan.filter(x=>x.d===d&&!x.exam).reduce((a,x)=>a+x.mins,0);if(dm+t.mins<=goal){t.d=d;mins-=t.mins;moved++;break}}})}},{after:()=>toast(moved?`${moved} sistem görevi daha boş günlere taşındı. Öğretmen görevleri yerinde kaldı.`:'Plan zaten dengeli; taşımaya gerek yok.')})};
ACT.vMeth=el=>{const x=VMETHODS.find(y=>y.id===el.dataset.v);commit(`“${x.t}” önerisi ${vFirst()}’in planına eklendi`,()=>{let d=isoAdd(stuToday(),1);while(DB.par.busy.includes(d))d=isoAdd(d,1);DB.st.plan.push({id:uid('pv'),title:x.task.title,course:'MAT',mins:x.task.mins,src:'Sistem',d,family:x.id==='anlat'});DB.st.notifs.unshift({id:uid('sn'),type:'Yeni etkinlik',text:`Velin bir çalışma yöntemi önerdi: ${x.t}.`,d:stuToday(),read:false,to:'o-plan'})})};

/* ================= 7) BAŞARILARI (tek sayfa, illüstrasyonlu) ================= */
PAGES['v-basari']=()=>{const S=DB.st;const L=lvlOf(S.xp);const earned=BADGES.filter(b=>{const[a,n]=b.prog();return a>=n});const set=new Set(S.streak);
  return {title:'Başarıları',crumbs:vCr(['Başarıları','']),html:`
  <section class="vtroph"><div class="vt-art">${VTROPHY}</div><div class="sp"><span class="eyebrow" style="color:#fff;opacity:.85">Motivasyon katmanı</span><h2 class="o-h" style="font-size:28px;color:#fff;margin:4px 0">Seviye ${L.lv} · ${num(S.xp)} XP</h2><div class="vxp"><i style="width:${L.cur/L.next*100}%"></i></div><p style="margin:6px 0 0;opacity:.95">Bir sonraki seviyeye <b>${L.next-L.cur} XP</b> kaldı · ${earned.length}/${BADGES.length} rozet</p></div>${naviFig('celebrate',150)}</section>
  <div class="grid g2 vbasg">
   <section class="ocard vstreak"><div class="row" style="flex-wrap:nowrap;gap:16px">${vFlame(curStreak(),84)}<div><h2 class="o-h" style="margin:0">${curStreak()} günlük seri</h2><div class="small muted">En uzun seri: ${S.best} gün · her gün en az 5 dakika çalışınca seri sürer</div></div></div>
    <div class="vstk">${Array.from({length:14},(_,i)=>{const iso=isoAdd(stuToday(),i-13);const on=set.has(iso)||(iso===stuToday()&&curStreak()>0&&(S.minutes[iso]||0)+S.secToday/60>=5);return `<span class="${on?'on':''}" title="${fmtD(iso)}">${on?vFlame('',22):'<i></i>'}<small>${+iso.slice(8)}</small></span>`}).join('')}</div></section>
   <section class="ocard"><h2 class="o-h">Seviye yolu</h2><div class="vpath">${Array.from({length:5},(_,i)=>{const lv=Math.max(1,L.lv-2)+i;const st=lv<L.lv?'done':lv===L.lv?'cur':'lock';return `<div class="vpn ${st}" style="--off:${[0,40,-30,30,-10][i]}px"><span>${st==='lock'?ic('lock',22):st==='done'?ic('check',22):`<b>${lv}</b>`}</span><small>Seviye ${lv}</small></div>`}).join('')}</div></section></div>
  <section class="ocard"><div class="card-hd"><div class="t"><h2 class="o-h">Rozetleri</h2><div class="meta">Kazanılan ve kilitli rozetler · her rozetin açılma koşulu yazılıdır</div></div></div>
   <div class="vbadges">${BADGES.map(b=>{const[a,n]=b.prog();const ok=a>=n;return `<div class="vbd ${ok?'ok':''}"><div class="vbd-i">${badgeSVG(b.st,!ok)}</div><b>${esc(b.t)}</b><span class="small muted">${esc(b.c)}</span><div class="pbar" style="margin-top:6px"><i style="width:${a/n*100}%;--c:${ok?'#2E9E6B':'#E0A04B'}"></i></div><small class="${ok?'okt':''}">${ok?'Kazanıldı':a+'/'+n}</small></div>`}).join('')}</div></section>
  <section class="ocard navi-card"><div class="row" style="flex-wrap:nowrap">${navi('celebrate',60)}${bubble(`<b>Birlikte kutlayın:</b> ${earned.length?`${esc(vFirst())} “${earned[0].t}” rozetini kazandı. Sonuçtan çok emeğini övmek motivasyonu en çok artıran şeydir.`:'İlk rozet geldiğinde size bildirim göndereceğim.'}`)}</div></section>`}};

/* ================= 8) ARKADAŞIM NAVİ (veli) ================= */
const VSTART=['Evde nasıl destek olurum?','Bu hafta neler yaptı?','Sınava nasıl hazırlanıyor?','Günde ne kadar çalışmalı?','Motivasyonu düştü, ne yapmalıyım?'];
function vReply(q){const S=DB.st,f=vFirst();const t=q.toLocaleLowerCase('tr');const k=lastWeakKz();const ex=DB.exams.find(x=>x.sections.includes(myStu().section)&&x.status==='Planlandı');
  if(t.includes('destek')||t.includes('evde'))return {pose:'explain',t:`${f} şu an <b>${esc(kzOf(k).topic)}</b> konusunda destek istiyor olabilir. Önerim: ${esc(vHomeIdea(k).items[0])} Çözümü siz vermeyin; “Nasıl düşündün?” diye sorun.`};
  if(t.includes('hafta')||t.includes('yaptı'))return {pose:'review',t:`Bu hafta ${S.solvedWeek} soru çözdü, ilk denemede ${S.correctWeek} doğru yaptı ve ${curStreak()} günlük serisini sürdürüyor. ${Object.keys(S.doneSets).length} etkinlik tamamlandı.`};
  if(t.includes('sınav'))return {pose:'plan',t:ex?`${esc(ex.name)} ${fmtDL(ex.date)} tarihinde (${daysBetween(stuToday(),ex.date)} gün). Konular: ${ex.kz.map(x=>esc(kzOf(x).topic)).join(', ')}. Sınavlar sayfasından “hazırlık öner” ile plana kısa görevler ekleyebilirsiniz.`:'Yakın tarihte planlanmış sınav görünmüyor.'};
  if(t.includes('ne kadar')||t.includes('süre')||t.includes('ekran'))return {pose:'plan',t:`7. sınıf için okul dışında günde <b>${PS().goal} dakikalık</b> odaklı çalışma yeterli; 20 dakikada bir 5 dakikalık mola önerilir. Hedefi Ayarlar’dan değiştirebilirsiniz.`};
  if(t.includes('motivasyon')||t.includes('isteksiz'))return {pose:'smile',t:`Küçük ve ulaşılabilir hedefler koyun, sonucu değil çabayı övün. ${f}’in sevdiği etkinlikler simülasyonlar; bir sonraki görevi onunla başlatmak iyi olabilir.`};
  if(t.includes('öğretmen'))return {pose:'present',t:`Okulun veli görüşme günlerinde öğretmene şunları sorabilirsiniz: “Sınıfta hangi konularda zorlanıyor?”, “Evde hangi alıştırma faydalı olur?”. Bu panelde öğretmenin paylaştığı geri bildirimleri Çalışma Alanı ve Bildirimler’de görebilirsiniz.`};
  return {pose:'thinking',t:'Bu prototipte kurallı yanıtlar var. Aşağıdaki hazır sorulardan birini seçebilirsiniz.'}}
PAGES['v-navi']=()=>{ensurePar();const ch=DB.par.chat;if(!ch.length)ch.push({f:'ai',pose:'welcome',t:`Merhaba ${esc(vHi())}! Ben Navi, ${esc(vFirst())}’in öğrenme arkadaşıyım. Evde nasıl destek olabileceğiniz konusunda size yardımcı olurum. Cevapları doğrudan söylemem; yöntem öneririm.`});
  const topics=[...new Set(DB.st.attempts.map(a=>kzOf(a.kz).topic))].slice(-5);
  return {title:'Arkadaşım Navi',crumbs:vCr(['Arkadaşım Navi','']),html:`<div class="asst"><section class="ocard chatc"><div class="row ctxbar">${navi(UI.vtyping?'process':'welcome',40)}<div class="sp"><b>Navi · veli asistanı</b><div class="meta">Demo modu · kurallı yanıtlar</div></div></div>
   <div class="chat" id="chat">${ch.map(m=>m.f==='me'?`<div class="msg me">${esc(m.t)}</div>`:`<div class="amsg">${navi(m.pose||'welcome',40)}<div class="msg ai">${m.t}</div></div>`).join('')}${UI.vtyping?`<div class="amsg">${navi('process',40)}<div class="msg ai"><span class="typing"><i></i><i></i><i></i></span></div></div>`:''}</div>
   <div class="row" style="gap:6px">${VSTART.map(s=>`<button class="pill p-out chipb" data-act="vSay" data-v="${esc(s)}">${esc(s)}</button>`).join('')}</div>
   <div class="row" style="flex-wrap:nowrap"><textarea class="ta" id="vIn" style="min-height:46px;height:46px" placeholder="Navi’ye sorun…" aria-label="Navi’ye mesaj"></textarea><button class="btn pri" data-act="vSend" aria-label="Gönder">${ic('send',16)}</button></div></section>
   <aside class="ocard pvc"><div class="stbox" style="padding:10px 0">${naviFig('smile',150)}</div><h3 class="o-h" style="font-size:17px">${esc(vFirst())}’in Navi ile çalıştığı konular</h3><div class="row" style="gap:6px;margin:8px 0">${topics.map(t=>`<span class="spill sp-sys">${esc(t)}</span>`).join('')||'<span class="meta">Henüz yok</span>'}</div><div class="meta">${ic('lock',12)} Sohbet içerikleri gizlidir; veliye yalnızca konu başlıkları gösterilir. Bu ayar Ayarlar › Gizlilik’te açıklanır.</div></aside></div>`,after:()=>{const c=$('#chat');if(c)c.scrollTop=c.scrollHeight}}};
function vAsk(q){if(!q.trim())return;DB.par.chat.push({f:'me',t:q});UI.vtyping=1;save();render();setTimeout(()=>{UI.vtyping=0;const r=vReply(q);DB.par.chat.push({f:'ai',...r});save();if(UI.route==='v-navi')render()},700)}
ACT.vSay=el=>vAsk(el.dataset.v);ACT.vSend=()=>{const v=$('#vIn').value;vAsk(v)};

/* ================= 9) BİLDİRİMLER ================= */
PAGES['v-bildirim']=()=>{const all=vNotifs();const t=UI.vnt||'';const types=[...new Set(all.map(n=>n.type))];const ls=all.filter(n=>!t||n.type===t);
  const icn={'Yeni etkinlik':'clip','Sınav':'cal','Tekrar zamanı':'repeat','Öğretmen geri bildirimi':'clipcheck','Rozet':'flag','Haftalık özet':'chart','Dikkat gerektiren':'alert','Öğretmen mesajı':'msg'};
  return {title:'Bildirimler',crumbs:vCr(['Bildirimler','']),html:`<section class="ocard"><div class="row" style="margin-bottom:10px"><div class="row" style="gap:6px">${['',...types].map(x=>`<button class="pill ${t===x?'p-ink':'p-out'} chipb" data-act="vnt" data-v="${x}">${x||'Tümü'}</button>`).join('')}</div><span class="sp"></span><button class="btn sm ghost" data-act="vReadAll">Tümünü okundu say</button></div>
   <div class="col" style="gap:6px">${ls.map(n=>`<button class="trow nrow ${n.read?'':'unread'}" style="width:100%;text-align:left" data-act="vN" data-v="${n.id}"><span class="cic" style="background:#F6ECDB;color:#810000">${ic(icn[n.type]||'bell',18)}</span><span class="sp"><b class="small">${n.type}</b> ${n.read?'':'<span class="spill sp-go">Yeni</span>'}<br><span class="small">${esc(n.text)}</span></span><span class="meta">${fmtD(n.d)}</span></button>`).join('')||stateBox('empty','Bildirim yok','')}</div></section>`}};
ACT.vnt=el=>{UI.vnt=el.dataset.v;render()};
ACT.vReadAll=()=>{DB.par.read=[...new Set([...DB.par.read,...vNotifs().map(n=>n.id)])];save();render()};
ACT.vN=el=>{const n=vNotifs().find(x=>x.id===el.dataset.v);if(!DB.par.read.includes(n.id))DB.par.read.push(n.id);if(n.type==='Öğretmen mesajı'){const th=vThread();if(th)th.parUnread=false}save();go(n.to)};

/* 10) Mesajlar kaldırıldı: veli panelinden öğretmene soru gönderilmez */
function vThread(){return null}
/* ================= 11) AYARLAR (ayrıntılı) ================= */
PAGES['v-ayarlar']=()=>{ensurePar();const S=PS();const sw=(k,l,d)=>`<div class="row setr"><span class="sp"><b class="small">${l}</b>${d?`<br><span class="meta">${d}</span>`:''}</span><button class="sw-t" role="switch" aria-checked="${!!S[k]}" aria-label="${l}" data-act="vSet" data-v="${k}"></button></div>`;
  const sel=(k,l,opts,d)=>`<div class="row setr"><span class="sp"><b class="small">${l}</b>${d?`<br><span class="meta">${d}</span>`:''}</span><select class="sel" style="max-width:220px" data-chg="vSel" data-k="${k}" aria-label="${l}">${opts.map(o=>{const v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return `<option ${String(S[k])===String(v)?'selected':''} value="${v}">${l}</option>`}).join('')}</select></div>`;
  const sec=(id,icn,t,body,d)=>`<section class="ocard vset" id="${id}"><div class="row" style="margin-bottom:6px"><span class="cic" style="background:#F6ECDB;color:#810000">${ic(icn,18)}</span><div class="sp"><h2 class="o-h" style="margin:0">${t}</h2>${d?`<div class="meta">${d}</div>`:''}</div></div>${body}</section>`;
  const toc=[['s-bil','Bildirimler'],['s-ozet','Haftalık özet'],['s-hedef','Çalışma hedefleri'],['s-saglik','Ekran ve sağlık'],['s-giz','Gizlilik ve veri'],['s-dil','Dil ve erişilebilirlik'],['s-bag','Bağlı öğrenciler'],['s-guv','Hesap güvenliği'],['s-demo','Demo']];
  return {title:'Ayarlar',crumbs:vCr(['Ayarlar','']),html:`<div class="vsetw"><nav class="ocard vtoc" aria-label="Ayar bölümleri">${toc.map(([id,l])=>`<button data-act="vToc" data-v="${id}">${l}</button>`).join('')}</nav><div class="col">
  ${sec('s-bil','bell','Bildirimler',`<div class="eyebrow" style="margin:6px 0">Kanallar</div>${sw('chApp','Uygulama içi','Panelde ve mobil uygulamada')}${sw('chMail','E-posta',esc(DB.par.prof.email))}${sw('chSms','SMS',esc(DB.par.prof.phone)+' · yalnızca acil durumlar')}
   <div class="eyebrow" style="margin:12px 0 6px">Bildirim türleri</div>${sw('tAct','Yeni etkinlik','Öğretmen görev atadığında')}${sw('tExam','Sınav hatırlatmaları','Sınavdan 7 ve 1 gün önce')}${sw('tBadge','Rozet ve başarılar','')}${sw('tRev','Tekrar zamanı','Aralıklı tekrar günleri')}${sw('tAlert','Dikkat gerektiren durumlar','Tekrarlayan zorluk ya da 3 gün çalışılmadığında')}
   <div class="eyebrow" style="margin:12px 0 6px">Sessiz saatler</div>${sw('quiet','Sessiz saatler','Bu aralıkta bildirim gönderilmez')}${S.quiet?`<div class="row setr"><span class="sp small">Aralık</span><input class="in" type="time" value="${S.qFrom}" data-chg="vSel" data-k="qFrom" aria-label="Başlangıç" style="width:120px">–<input class="in" type="time" value="${S.qTo}" data-chg="vSel" data-k="qTo" aria-label="Bitiş" style="width:120px"></div>`:''}`)}
  ${sec('s-ozet','chart','Haftalık özet raporu',`${sw('tWeek','Haftalık özet gönder','Çalışma süresi, tamamlanan görevler, gözlenen ihtiyaç')}${sel('sumDay','Gönderim günü',['Cuma','Cumartesi','Pazar','Pazartesi'])}${sel('sumTime','Saat',['08:00','12:00','19:00','21:00'])}${sel('sumFmt','Biçim',['Uygulama','Uygulama + e-posta (PDF)','Yalnızca e-posta (PDF)'])}<div class="row" style="justify-content:flex-end;margin-top:8px"><button class="btn sm sec" data-act="vReport">${ic('dl',14)} Örnek raporu önizle</button></div>`)}
  ${sec('s-hedef','target','Çalışma hedefleri',`${sel('goal','Günlük çalışma hedefi',[['15','15 dakika'],['20','20 dakika'],['30','30 dakika'],['45','45 dakika']],'Navi planı dengelerken bu sınırı kullanır')}${sw('weekend','Hafta sonu çalışma','Kapalıysa sistem görevleri hafta içine taşınır')}<div class="row setr"><span class="sp"><b class="small">Aile zamanı günleri</b><br><span class="meta">${DB.par.busy.length?DB.par.busy.map(fmtD).join(', '):'Tanımlı gün yok'}</span></span><button class="btn sm sec" data-go="v-plan">Takvimde düzenle</button></div>`,'Öğretmen atamaları değişmez; yalnızca sistem önerileri uyarlanır')}
  ${sec('s-saglik','clock','Ekran ve sağlık',`${sw('breakRem','Mola hatırlatıcı','20 dakikalık çalışmadan sonra 5 dakika mola önerir')}${sw('night','Gece kullanım uyarısı','21:30’dan sonra çalışma başlatılırsa size bildirir')}`)}
  ${sec('s-giz','lock','Gizlilik ve veri',`<div class="row setr"><span class="sp"><b class="small">Navi sohbet içerikleri</b><br><span class="meta">Öğrencinin güvenle soru sorabilmesi için içerik gösterilmez; yalnızca konu başlıkları</span></span><span class="spill sp-wait">${ic('lock',12)} Kapalı (sabit)</span></div>${sw('navTopics','Sohbet konu başlıklarını göster','Arkadaşım Navi sayfasında')}${sw('share','Anonim kullanım verisiyle ürün geliştirmeye katkı','Kişisel veri paylaşılmaz (KVKK)')}<div class="row" style="gap:8px;margin-top:8px"><button class="btn sm sec" data-act="vInfo" data-v="kvkk">KVKK aydınlatma metni</button><button class="btn sm sec" data-act="vInfo" data-v="veri">Verilerimi indir</button></div>`)}
  ${sec('s-dil','user','Dil ve erişilebilirlik',`${sel('lang','Arayüz dili',['Türkçe','English'])}${sel('vtext','Yazı boyutu',['Küçük','Normal','Büyük'])}${sel('tts','Sesli okuma hızı',['Yavaş','Normal','Hızlı'])}${sw('contrast','Yüksek kontrast','Metin ve kenarlıkları belirginleştirir')}`)}
  ${sec('s-bag','users','Bağlı öğrenciler',`<div class="trow"><span class="av" style="background:${DB.st.avatar};color:#fff;width:36px;height:36px;border-radius:50%;display:grid;place-items:center;font-weight:800">EY</span><div class="sp"><b>${esc(fullName(myStu()))}</b><div class="meta">${TEACHER.org} · ${myStu().section} · rehber öğretmen ${TEACHER.name}</div></div><span class="spill sp-done">Bağlı</span></div><button class="btn sm sec" style="margin-top:10px" data-act="vInfo" data-v="ekle">${ic('plus',14)} Okul koduyla öğrenci ekle</button>`,'Şube ve ders bilgisi okul tarafından yönetilir')}
  ${sec('s-guv','shield','Hesap güvenliği',`<div class="row setr"><span class="sp"><b class="small">Şifre</b><br><span class="meta">Son değişiklik: 12 Eylül 2026</span></span><button class="btn sm sec" data-act="vInfo" data-v="sifre">Değiştir</button></div>${sw('twofa','İki adımlı doğrulama','Girişte telefonunuza kod gönderilir')}<div class="row setr"><span class="sp"><b class="small">Açık oturumlar</b><br><span class="meta">Bu cihaz · iPhone (mobil uygulama)</span></span><button class="btn sm sec" data-act="vInfo" data-v="oturum">Diğerlerini kapat</button></div>`)}
  ${sec('s-demo','refresh','Demo',`<div class="row setr"><span class="sp"><b class="small">Demo verisini sıfırla</b><br><span class="meta">Tüm değişiklikler başlangıç hâline döner</span></span><button class="btn sm sec" data-act="resetDo">Sıfırla</button></div>`)}
  </div></div>`}};
ACT.vSet=el=>{const k=el.dataset.v;PS()[k]=PS()[k]?0:1;save();render();toast('Ayar kaydedildi')};
ACT.vSel=el=>{PS()[el.dataset.k]=el.value;if(el.dataset.k==='vtext')DB.st.settings.text=el.value;save();render();toast('Ayar kaydedildi')};
ACT.vToc=el=>{const t=$('#'+el.dataset.v);t&&t.scrollIntoView({behavior:'smooth',block:'start'})};
ACT.vInfo=el=>{const M={kvkk:['KVKK aydınlatma metni','Okulunuz veri sorumlusudur. NavigAItor yalnızca öğrenme desteği amacıyla, okulun tanımladığı kapsamda veri işler. (Demo metni)'],veri:['Verilerimi indir','Talebiniz alındı. Hazır olduğunda e-posta adresinize indirme bağlantısı gönderilir. (Demo)'],ekle:['Öğrenci ekle','Okulunuzun verdiği öğrenci kodunu girerek ikinci bir öğrenciyi bağlayabilirsiniz. (Demo)'],sifre:['Şifre değiştir','Şifre değiştirme bağlantısı e-posta adresinize gönderildi. (Demo)'],oturum:['Oturumlar','Diğer cihazlardaki oturumlar kapatıldı. (Demo)']}[el.dataset.v];openModal(()=>({title:M[0],body:`<p>${M[1]}</p>`,foot:`<button class="btn pri" data-act="closeLayer">Tamam</button>`}))};
ACT.vReport=()=>{const S=DB.st;openModal(()=>({title:`Haftalık özet · ${vFirst()}`,sub:`${fmtD(vMon())} – ${fmtD(isoAdd(vMon(),6))} · ${PS().sumFmt}`,body:`<div class="grid g3" style="gap:10px"><div class="eb" style="--c:#2F7DD8"><span>Çözülen soru</span><b>${S.solvedWeek}</b></div><div class="eb" style="--c:#2E9E6B"><span>İlk denemede doğru</span><b>${S.correctWeek}</b></div><div class="eb" style="--c:#E0A04B"><span>Seri</span><b>${curStreak()} gün</b></div></div><p class="small" style="margin-top:12px">Öne çıkan: ${esc(kzOf(lastWeakKz()).topic)} konusunda kısa tekrar planlandı. Evde destek önerisi panelde.</p>`,foot:`<button class="btn pri" data-act="closeLayer">Kapat</button>`}))};

/* ================= 12) PROFİL ================= */
PAGES['v-profil']=()=>{ensurePar();const p=vPar(),P=DB.par.prof;const ini=p.name.split(' ').map(x=>x[0]).join('').slice(0,2);
  return {title:'Profil',crumbs:vCr(['Profil','']),html:`<div class="grid g2"><section class="ocard"><div class="row"><span class="av" style="width:72px;height:72px;border-radius:50%;background:${DB.par.avatar};color:#fff;display:grid;place-items:center;font-size:26px;font-weight:800">${ini}</span><div class="sp"><h2 class="o-h" style="margin:0">${esc(p.name)}</h2><div class="meta">Veli · ${P.rel}</div></div></div>
   <div class="eyebrow" style="margin:14px 0 6px">Avatar rengi</div><div class="row" style="gap:8px">${['#6D5BD0','#2F7DD8','#2E9E6B','#E07A2F','#C2408A','#810000'].map(c=>`<button class="cdotb ${DB.par.avatar===c?'on':''}" style="background:${c}" data-act="vAv" data-v="${c}" aria-label="Avatar rengi ${c}"></button>`).join('')}</div>
   <div class="col" style="gap:10px;margin-top:14px"><label class="sfl"><span>Telefon</span><input class="in" value="${esc(P.phone)}" data-chg="vProf" data-k="phone"></label><label class="sfl"><span>E-posta</span><input class="in" value="${esc(P.email)}" data-chg="vProf" data-k="email"></label><label class="sfl"><span>Ulaşılabilir olduğum saatler</span><input class="in" value="${esc(P.contact)}" data-chg="vProf" data-k="contact"></label></div></section>
   <section class="ocard"><h2 class="o-h">Okul verisi</h2><div class="meta" style="margin-bottom:10px">${ic('lock',12)} Okul tarafından yönetilir; veli tarafından değiştirilemez</div>${[['Kurum',TEACHER.org],['Öğrenci',fullName(myStu())],['Şube',myStu().section],['Rehber öğretmen',TEACHER.name],['Yakınlık',P.rel]].map(([a,b])=>`<div class="row setr"><span class="sp small muted">${a}</span><b class="small">${esc(b)}</b></div>`).join('')}</section></div>`}};
ACT.vAv=el=>{DB.par.avatar=el.dataset.v;save();render()};
ACT.vProf=el=>{DB.par.prof[el.dataset.k]=el.value;save();toast('Profil güncellendi')};

/* ---------- ayrı uygulama: yalnızca veli rotaları ---------- */
const _vRender=render;render=function(e){if(!UI.route||!UI.route.startsWith('v-')){location.hash='v-home';return}ensureStu();ensurePar();_vRender(e);document.body.classList.toggle('hc',!!PS().contrast)};
drawDemo=function(){const d=$('#demo');if(d)d.remove()};

ACT.vgAll=()=>{UI.vgAll=!UI.vgAll;render()};

PAGES['v-mesaj']=()=>{setTimeout(()=>go('v-home'));return {title:'Ana Sayfa',crumbs:vCr(),html:''}};
